[asy]
pair A,B,C,D,M,N,O;
A=(227.2,310.4);
B=(0,0);
C=(1000,0);
D=(2008,0);
O=(1004,0);
M=(500,0);
N=(1004,0);
draw(A--B--C--D--cycle,dashed);
draw(A--O--D,dashed);
draw(rightanglemark(A,B,O,5));
draw(rightanglemark(A,D,O,5));
draw(rightanglemark(B,C,O,5));
label("A",A,N);
label("B",B,SW);
label("C",C,SE);
label("D",D,dir(0));
label("O",O,S);
label("M",M,S);
label("N",N,E);
label("37",midpoint(A--B),NW);
label("37",midpoint(B--C),NE);
label("43",midpoint(C--D),NE);
label("37",midpoint(D--A),NW);
label("43",midpoint(A--O),W);
label("1000",midpoint(B--C),S);
label("2008",midpoint(A--D),S);
[/asy]
